// World state lives on the board; the view is optional and owns no simulation facts.
let lastWorldSave=0;
async function worldChange(transform,{record=true}={}){
 if(busy||worldWorking)return;worldWorking=true;refreshHistoryControls();
 try{const next={...board,revision:board.revision+1,world:sealWorld(transform(board.world))};board=next;if(record)history.commit(next);else history.checkpoint(next);actionRevision++;render();if(outbreak)refreshDashboard();worldUI?.refresh();if(record||performance.now()-lastWorldSave>2000){await persistCurrent();lastWorldSave=performance.now();}window.RanchView?.changed();}
 catch(error){worldRunning=false;status(error.message);throw error;}finally{worldWorking=false;refreshHistoryControls();worldUI?.refresh();}
}
async function worldStep(seconds,record=true){if(!worldGraph||!board.world)return;const started=performance.now();return worldChange(w=>{let next=outbreak?w:advanceWorld(w,worldGraph,seconds);if(next.encounter&&Object.keys(next.actors||{}).length)next=advanceEncounter(next,worldGraph,seconds);worldTickCost=performance.now()-started;return next;},{record});}
async function worldExample(){
 if(busy||worldWorking)return;worldRunning=false;await startVillage('world-pair');
 if(board.settlement?.preset!=='world-pair')return;
 await worldChange(w=>{let next=w;for(const e of Object.values(w.entities).filter(e=>e.active&&e.kind==='place')){next=setAffinities(next,e.id,'tribal',['Willow kin']);next=setAffinities(next,e.id,'political',['River council']);next=setAffinities(next,e.id,'national',['Vale commonwealth']);}return next;},{record:false});
 selected=null;setMode('place');worldUI.open();focusSettlement();status('Connected world example · membership and fuel journeys are live. Undo restores the previous board.');
}
worldUI=(outbreak?createOutbreakPanel:createWorldPanel)({container:$('create-drawer'),toolbar:$('sandbox-tools'),read:()=>({world:board.world,running:worldRunning,busy:busy||worldWorking,selected,board,cost:worldTickCost}),
 onOpen:()=>{setMode('place');$('create-drawer').hidden=false;$('drawer-toggle').setAttribute('aria-expanded','true');fit(true);},onStep:s=>worldStep(s).catch(e=>worldUI.feedback(e.message)),onRun:()=>{worldRunning=!worldRunning;if(!worldRunning)persistCurrent();worldUI.refresh();},onExample:()=> (outbreak?outbreakExample():worldExample()).catch(e=>worldUI.feedback(e.message)),onMatchup:()=>outbreakExample('brooms').catch(e=>worldUI.feedback(e.message)),onScenario:name=>outbreakExample(name).catch(e=>worldUI.feedback(e.message)),onProfile:(id,settings)=>worldChange(w=>setActorProfile(w,id,settings)),onConditions:changes=>worldChange(w=>setWorldConditions(w,changes)),onRelationship:(a,b,value)=>worldChange(w=>setRelationship(w,a,b,value)),onReinforce:(instanceId,count)=>worldChange(w=>spawnActors(w,board,worldGraph,instanceId,count)).catch(e=>worldUI.feedback(e.message)),onEquip:()=>worldChange(w=>equipPeople(w,'broom')),onBoost:team=>worldChange(w=>strengthen(w,team)),onSpawn:team=>{const i=board.instances.find(i=>board.cards[cardKey(i.cardId,i.cardRevision)]?.type===(team==='undead'?'zombies':'brains'));if(!i){worldUI.feedback('Place a '+(team==='undead'?'Zombies':'Brains')+' tile first.');return;}return worldChange(w=>spawnActors(w,board,worldGraph,i.instanceId,4)).catch(e=>worldUI.feedback(e.message));},
 onApply:(id,changes)=>worldChange(w=>changes.reduce((next,c)=>setAffinities(next,id,c.kind,c.names,{inherit:c.inherit}),w)),onPolicy:value=>worldChange(w=>({...w,policy:{...w.policy,preferFamiliar:value}})),
 onFocus:instanceId=>{if(instanceId){chooseInstance(instanceId);worldUI.open();fit(true,true);}}
});
worldUI.refresh();
let worldTimerBusy=false;
setInterval(async()=>{if(!worldRunning||document.hidden||busy||worldWorking||worldTimerBusy||drag)return;worldTimerBusy=true;try{await worldStep(outbreak?worldUI.speed()*.25:worldUI.speed(),false);}catch{worldRunning=false;}finally{worldTimerBusy=false;}},outbreak?250:1000);
setInterval(()=>worldUI.refresh(),500);
document.addEventListener('visibilitychange',()=>{if(document.hidden){worldRunning=false;persistCurrent();worldUI.refresh();}});
window.RanchView?.register('world',()=>({report:board.world?(outbreak?encounterReport(board.world):worldReport(board.world)):null,running:worldRunning,conditions:conditionsOf(board.world||{}),scope:outbreak?'Shared actors, budgeted navigation, projectiles, burning and explicit relationships; fixed steps, no offline catch-up':'Persistent affinities and Home–Woodland fuel journeys; other economies remain separate'}));
if(outbreak){document.title='Outbreak · Sandbox';document.querySelector('.board-heading h1').textContent='Outbreak';}if(outbreak||new URLSearchParams(location.search).get('world')==='1')worldUI.open();

function encounterEntries(preset){
 const entry=(type,preset,seed,q,r)=>({type,preset,seed,q,r});
 if(preset==='outbreak-wizards')return [entry('zombies','horde',41,0,0),entry('wizard','apprentice',63,0,1)];
 if(preset==='outbreak-rabbits')return [entry('rabbits','grove',41,0,0),entry('rabbits','predator',63,0,1)];
 if(preset==='outbreak-crowd')return [entry('zombies','horde',41,0,0),entry('brains','brooms',63,0,1)];
 if(['outbreak-nations','outbreak-clans','outbreak-divided-family','outbreak-ceasefire'].includes(preset))return [entry('wizard','circle',41,0,0),entry('wizard','circle',63,0,1)];
 if(preset==='outbreak-alliance')return [entry('brains','guards',41,0,0),entry('wizard','circle',63,0,1),entry('zombies','horde',73,1,0)];
 if(preset==='outbreak-ecosystem')return [entry('zombies','stragglers',41,0,0),entry('wizard','apprentice',63,0,1),entry('rabbits','grove',73,1,0)];
 return [entry('zombies','stragglers',41,0,0),entry('brains',preset==='outbreak-brooms'?'brooms':'scouts',63,0,1)];
}
async function outbreakExample(preset='scouts'){
 if(busy||worldWorking)return;worldRunning=false;const key=preset==='scouts'?'outbreak':'outbreak-'+preset;
 const result=await startVillage(key);if(!result?.boardLoaded)return;
 if(preset==='crowd')await worldChange(w=>{let next=w;for(const instance of board.instances){let count=Object.values(next.actors).filter(a=>a.instanceId===instance.instanceId&&a.hp>0).length;while(count<256){const amount=Math.min(32,256-count);next=spawnActors(next,board,worldGraph,instance.instanceId,amount);count+=amount;}}return next;},{record:false});
 if(FACTION_SCENARIOS[preset])await worldChange(w=>applyFactionScenario(w,board,preset),{record:false});
 selected=null;setMode('place');worldUI.open();focusSettlement();status('Press Run. Actors follow shared rules; Undo restores your previous board.');
}
